#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int countBalls(int lowLimit, int highLimit) {
        vector<int> boxes(50, 0);
        int max_balls = 0;
        for (int num = lowLimit; num <= highLimit; ++num) {
            int s = 0, n = num;
            while (n > 0) {
                s += n % 10;
                n /= 10;
            }
            boxes[s]++;
            if (boxes[s] > max_balls) max_balls = boxes[s];
        }
        return max_balls;
    }
};

class Solution {
    public int countBalls(int lowLimit, int highLimit) {
