/**
 * @param {number} lowLimit
 * @param {number} highLimit
 * @return {number}
 */
var countBalls = function(lowLimit, highLimit) {
    const boxes = Array(50).fill(0);
    let maxBalls = 0;
    for (let num = lowLimit; num <= highLimit; ++num) {
        let s = 0, n = num;
        while (n > 0) {
            s += n % 10;
            n = Math.floor(n / 10);
        }
        boxes[s]++;
        if (boxes[s] > maxBalls) maxBalls = boxes[s];
    }
    return maxBalls;
};
